using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.RegularExpressions;
using Jobbliggaren.Application.JobAds.Abstractions;

namespace Jobbliggaren.Infrastructure.Taxonomy;

/// <summary>
/// #2199 — loads the committed <c>occupation-name-lineage.json</c> (generated by
/// <c>tools/taxonomy-snapshot/generate-occupation-name-lineage.mjs</c>) into the Application's
/// <see cref="OccupationNameLineage"/>. The file shape stays here; nothing past Infrastructure sees it.
///
/// <para>
/// It runs once at host start (the provider is registered as an instance), so a malformed artefact
/// stops the host instead of a search. This class checks the form; the lineage's constructor checks
/// duplicates, unknown targets and cycles.
/// </para>
/// </summary>
internal static partial class OccupationNameLineageLoader
{
    private const string ResourceName = "Jobbliggaren.Infrastructure.Taxonomy.occupation-name-lineage.json";

    // The search read path's concept-id grammar (ListJobAdsQueryValidator), so every id the lineage
    // can expand a pick into is one the filter accepts.
    [GeneratedRegex(@"^[A-Za-z0-9_-]{1,32}\z")]
    private static partial Regex ConceptIdPattern();

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = false,
        ReadCommentHandling = JsonCommentHandling.Disallow,
    };

    internal static OccupationNameLineage Load()
    {
        using var stream = typeof(OccupationNameLineageLoader).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource {ResourceName} is missing.");
        return LoadFrom(stream);
    }

    /// <summary>Test seam: drives a synthetic stream through the real path.</summary>
    internal static OccupationNameLineage LoadFrom(Stream stream)
    {
        var file = JsonSerializer.Deserialize<LineageFile>(stream, JsonOptions)
            ?? throw new InvalidOperationException("The occupation-name lineage deserialised to null.");

        if (string.IsNullOrWhiteSpace(file.LineageVersion))
            throw new InvalidOperationException("The occupation-name lineage has no lineageVersion.");
        if (file.TaxonomyVersions is not { Count: > 0 } versions)
            throw new InvalidOperationException("The occupation-name lineage names no taxonomyVersions.");
        if (file.OccupationNames is not { Count: > 0 } names)
            throw new InvalidOperationException("The occupation-name lineage lists no occupation-names.");

        var entries = new List<OccupationNameLineageEntry>(names.Count);
        foreach (var name in names)
        {
            var id = RequireConceptId(name.ConceptId, "conceptId");
            if (name.GroupConceptId is not null)
                RequireConceptId(name.GroupConceptId, $"the group of {id}");

            var currentIn = name.CurrentIn ?? [];
            if (currentIn.FirstOrDefault(v => !versions.Contains(v)) is { } unknownVersion)
                throw new InvalidOperationException($"{id} is current in {unknownVersion}, which taxonomyVersions does not list.");
            if (currentIn.Count > 0 && name.GroupConceptId is null)
                throw new InvalidOperationException($"{id} is current but has no group.");

            var replacedBy = name.ReplacedByConceptIds ?? [];
            foreach (var target in replacedBy)
                RequireConceptId(target, $"a replacement of {id}");

            entries.Add(new OccupationNameLineageEntry(id, name.GroupConceptId, currentIn, replacedBy));
        }

        return new OccupationNameLineage(file.LineageVersion, entries);
    }

    private static string RequireConceptId(string? value, string what) =>
        value is not null && ConceptIdPattern().IsMatch(value)
            ? value
            : throw new InvalidOperationException($"The occupation-name lineage has an invalid concept id for {what}: '{value}'.");

    private sealed record LineageFile(
        [property: JsonPropertyName("lineageVersion")] string? LineageVersion,
        [property: JsonPropertyName("taxonomyVersions")] IReadOnlyList<string>? TaxonomyVersions,
        [property: JsonPropertyName("occupationNames")] IReadOnlyList<LineageFileEntry>? OccupationNames);

    private sealed record LineageFileEntry(
        [property: JsonPropertyName("conceptId")] string? ConceptId,
        [property: JsonPropertyName("groupConceptId")] string? GroupConceptId,
        [property: JsonPropertyName("currentIn")] IReadOnlyList<string>? CurrentIn,
        [property: JsonPropertyName("replacedByConceptIds")] IReadOnlyList<string>? ReplacedByConceptIds);
}
